#!/usr/bin/env python3
"""Genera el informe web y la nota asociada desde datos trazables del proyecto."""
import json,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'deploy/site-overlay'
D=json.loads((SITE/'assets/data/presupuesto-2027.json').read_text())
def n(v,d=0):return f'{v:,.{d}f}'.replace(',','X').replace('.',',').replace('X','.')
def m(v):return '$ '+n(v/1e6,1)+' M'
def p(v):return ('+' if v>0 else '')+n(v,1)+'%'
health=next(x for x in D['funciones'] if x['nombre']=='Salud')
share_old=health['vigente_2026_06_30']/D['vigente_2026_06_30']*100
share_new=health['proyecto_2027']/D['total_2027']*100
gap=D['total_2027']*share_old/100-health['proyecto_2027']
rows=''.join(f'<tr><th scope="row">{html.escape(x["nombre"])}</th><td>{m(x["vigente_2026_06_30"])}</td><td>{m(x["proyecto_2027"])}</td><td>{p((x["proyecto_2027"]/x["vigente_2026_06_30"]-1)*100)}</td><td data-real-row="{i}">{p((x["proyecto_2027"]/x["vigente_2026_06_30"]/1.2154-1)*100)}</td></tr>' for i,x in enumerate(D['funciones']))
compo=''.join(f'<div class="p27-breakdown"><div><strong>{x["nombre"]}</strong><span>{m(x["monto"])}</span></div><div class="p27-bar"><i style="width:{x["monto"]/D["salud"]["funcion_total"]*100:.3f}%"></i></div><small>{n(x["monto"]/D["salud"]["funcion_total"]*100,1)}% de la función Salud</small></div>' for x in D['salud']['composicion_economica'])
works=''.join(f'<tr data-work-type="{w["tipo"]}" data-work-name="{html.escape(w["efector"])}"><th scope="row">{html.escape(w["efector"])}</th><td>{html.escape(w["obra"])}</td><td>{m(w["proyecto_2027"])}</td><td>{m(w["plan_2028"])}</td><td>{m(w["plan_2029"])}</td><td><a href="#fuentes" aria-label="Fuente de {html.escape(w["obra"])} en {html.escape(w["efector"])}">PPI · PDF p. {w["pagina_pdf"]}</a></td></tr>' for w in D['obras_seleccionadas'])
staff=''.join(f'<tr><th scope="row">{x["nombre"]}</th><td>{n(x["cargos"])}</td></tr>' for x in D['salud']['dotacion'])
communes=''.join(f'<tr><th scope="row">Comuna {x["comuna"]}</th><td>{m(x["proyecto_2027"])}</td></tr>' for x in D['comunas_entidad'])
sources=''.join(f'<li><a href="{html.escape(x["url"])}" target="_blank" rel="noopener">{html.escape(x["titulo"])}</a>'+ (f'<br>{html.escape(x["documento"])} · {html.escape(x["paginas"])}' if 'documento' in x else '')+'</li>' for x in D['fuentes'])
body=f'''
<main class="p27"><p class="p27-crumb"><a href="/presupuesto/">Presupuesto</a> / Proyecto 2027</p>
<header class="p27-hero"><div><span class="p27-kicker">PRESUPUESTO CABA 2027 · MIRADA DE 100 BARRIOS</span><h1>La salud pierde prioridad en el presupuesto de la Ciudad</h1><p>El proyecto aumenta los pesos asignados a Salud, pero reduce su participación en el gasto total. Desde los barrios, la discusión es qué recursos sostendrán los hospitales, los CeSAC y la atención que necesitamos.</p><div class="p27-meta">Proyecto presentado el 30/09/2026 · Análisis al 08/10/2026</div><a class="p27-action" href="/presupuesto/ejecucion/">Consultar la ejecución presupuestaria</a></div><aside><span>LA PREGUNTA SANITARIA</span><blockquote>¿El presupuesto garantiza más capacidad de atención donde más se necesita?</blockquote><p>Personal, insumos, prevención, salud mental y obras que lleguen a funcionar.</p></aside></header>
<div class="p27-stats"><div><b>{n(share_new,2)}%</b><span>del gasto para Salud</span><small>Antes: {n(share_old,2)}% · vigente 30/06/2026</small></div><div><b>+18,2%</b><span>suba nominal de Salud</span><small>$3,97 billones · proyecto 2027</small></div><div><b>−2,8%</b><span>poder de compra en el escenario del bloque</span><small>Inflación promedio estimada: 21,54%</small></div><div><b>$102.419 M</b><span>para conservar su participación anterior</span><small>Referencia distributiva calculada · 2027</small></div></div>
<p class="p27-source">Fuente: PDLEY-2026-36, Planilla 1; Mensaje, Cuadro 2.4. Cálculos propios. La pérdida de participación es independiente del escenario de inflación.</p>
<nav class="p27-index" aria-label="Secciones del informe"><a href="#prioridad">Prioridad sanitaria</a><a href="#atencion">Atención en los barrios</a><a href="#personal">Personal e insumos</a><a href="#salud-mental">Salud mental</a><a href="#obras">Obras por efector</a><a href="#contexto">El resto del presupuesto</a><a href="#propuestas">Qué proponemos</a><a href="#metodologia">Método y fuentes</a></nav>
<section id="prioridad"><span class="p27-kicker">01 · SALUD EN EL CENTRO</span><h2>Más pesos no equivalen a mayor prioridad</h2><p>La función Salud pasa de $3,36 billones de crédito vigente al 30 de junio de 2026 a $3,97 billones en el proyecto 2027. Su crecimiento nominal, 18,2%, queda por debajo del aumento del gasto total, 21,2%. Por eso pierde 0,43 puntos porcentuales de participación: del 16,89% al 16,46%.</p><p>Si Salud conservara su participación exacta de 2026, tendría aproximadamente $4,07 billones: $102.419 millones más que lo propuesto. Es una comparación de prioridades dentro del mismo presupuesto, útil para discutir su distribución. El monto expresa una asignación alternativa; no es una partida eliminada ni una deuda del Gobierno.</p><div class="p27-callout"><strong>La posición de 100 Barrios</strong><p>El presupuesto debe fortalecer la salud pública y reducir las desigualdades de acceso. La pérdida de peso de Salud exige una explicación del Ejecutivo y una discusión sobre los recursos necesarios para garantizar atención oportuna, condiciones de trabajo y continuidad de los tratamientos.</p></div><h3>El poder de compra depende de los precios del año</h3><p>Para comparar presupuestos anuales utilizamos precios promedio anuales. El 18% anunciado por Hacienda es una pauta de inflación al cierre del año; no reemplaza automáticamente la variación del promedio de precios de 2027 respecto de 2026.</p><div class="p27-explorer"><fieldset><legend>Comparar dos escenarios de inflación promedio</legend><label><input name="scenario" type="radio" value="bloque" checked> 21,54% · escenario del bloque</label><label><input name="scenario" type="radio" value="alternativo"> 23,00% · escenario alternativo</label></fieldset><div class="p27-scenario-result" aria-live="polite"><b id="health-real">−2,8%</b><span>variación real de Salud</span><small id="scenario-note">Proyecto 2027 frente al vigente 30/06/2026, con inflación promedio estimada de 21,54%.</small></div></div><p>Con la estimación alternativa de 23%, Salud pierde 3,9% de poder de compra. Ambos son ejercicios de escenario. La conclusión distributiva permanece: Salud crece menos que el gasto total.</p><h3>Qué presupuesto estamos comparando</h3><p>El análisis funcional usa una única base: el Cuadro 2.4 del Mensaje, con $19,88 billones vigentes y $7,10 billones devengados al 30/06/2026. El observatorio de ejecución utiliza una extracción que informa aproximadamente $20,88 billones vigentes y $7,67 billones devengados. La metodología del observatorio aclara que incluye aplicaciones financieras junto con gastos corrientes y de capital. Es un universo distinto del gasto funcional utilizado aquí. La conciliación exacta requiere cruzar clasificaciones económicas y funcionales; no se mezclan los totales de ambas pantallas.</p></section>
<section id="atencion"><span class="p27-kicker">02 · LA SALUD QUE LLEGA AL BARRIO</span><h2>Atención primaria, prevención y acceso efectivo</h2><p>El Mensaje describe una red de 51 CeSAC, tres Centros de Cuidados Integrales, 14 Centros Médicos Barriales y cuatro Centros de Diagnóstico Porteño. Enumera vacunación, el Plan de los 1.000 Días, tuberculosis, dengue, VIH e infecciones de transmisión sexual y enfermedades crónicas. Esa descripción expresa líneas de política: para evaluar su suficiencia necesitamos presupuestos, equipos y metas por establecimiento.</p><p>Desde 100 Barrios proponemos evaluar el gasto por la capacidad de resolver problemas cerca de donde vive cada persona. Los indicadores centrales deben incluir turnos disponibles, espera por especialidad, horarios de atención, dotación efectiva y continuidad de los medicamentos. Hoy este proyecto agregado permite discutir prioridades financieras; la medición de esas condiciones requiere información operativa adicional.</p><div class="p27-cards"><article><span>COMUNA 4</span><h3>Hospitales y red comunitaria</h3><p>Las obras del Argerich y del Penna permiten examinar guardias, consulta externa y cirugía. Borda, Moyano y Tobar García abren además la discusión sobre atención de salud mental y su articulación comunitaria.</p></article><article><span>COMUNA 7</span><h3>Atención primaria y áreas programáticas</h3><p>La lectura del Piñero debe articularse con la red de CeSAC y su área programática. Consulta externa, imágenes y centro obstétrico importan junto con los equipos y recursos para la atención cotidiana.</p></article><article><span>COMUNA 9</span><h3>Guardia y atención ambulatoria</h3><p>El Santojanni tiene prevista una ampliación de guardia y reorganización de consulta externa. Su utilidad debe evaluarse con cronograma, dotación, equipamiento y articulación con la atención primaria.</p></article></div><p class="p27-source">Son puertas territoriales de lectura, no montos imputados exclusivamente a residentes de cada comuna. Los hospitales atienden áreas que pueden atravesar límites administrativos.</p><h3>Cuidados, salud de las mujeres y derechos</h3><p>La evaluación debe incluir atención obstétrica, acceso a analgesia peridural, cuidados paliativos, rehabilitación y atención de personas mayores. La disponibilidad de presupuesto general no permite verificar por sí sola el financiamiento de cada prestación. Proponemos identificar las partidas y metas que sostienen estos derechos y su distribución en la red pública.</p><div class="p27-links"><a href="/territorio/equipamientos/">Consultar equipamientos en el territorio</a><a href="/legislatura/seguimiento/analgesia-peridural/">Seguimiento de analgesia peridural</a><a href="/observatorio/personas-mayores/">Personas mayores y cuidados</a></div></section>
<section id="personal"><span class="p27-kicker">03 · RECURSOS PARA ATENDER</span><h2>Personal, insumos y equipamiento funcionan juntos</h2><p>La función Salud y el Ministerio de Salud son dos recortes distintos. La primera agrupa el propósito del gasto y suma $3.966.269 millones; el segundo identifica quién lo administra y suma $3.986.127 millones. Para comparar prioridades utilizamos la función. Para examinar la dotación y la organización administrativa identificamos expresamente al Ministerio.</p><div class="p27-two"><div><h3>Composición de la función Salud</h3>{compo}<p class="p27-source">Planilla 1, carácter económico. Gastos de consumo reúne bienes y servicios; para distinguir medicamentos, limpieza o mantenimiento se requiere otra desagregación.</p></div><div><h3>Cargos previstos en el Ministerio</h3><table class="p27-simple"><caption>Proyecto 2027 · Planilla 17</caption><thead><tr><th scope="col">Categoría</th><th scope="col">Cargos</th></tr></thead><tbody>{staff}<tr><th scope="row">Total</th><td>42.395</td></tr></tbody></table><p class="p27-source">Son cargos presupuestados; la ocupación efectiva, vacantes, guardias y distribución por hospital o CeSAC necesitan datos complementarios.</p></div></div><p>Las remuneraciones representan 55,4% de la función Salud. El gasto en personal del Ministerio asciende a $2.133.229 millones. Incluye componentes diferentes del sueldo de bolsillo y proyecciones de negociación salarial. Dividirlo por cargos produce un costo presupuestario medio, no un salario individual ni una mejora salarial garantizada.</p><p>La crítica sanitaria debe evitar enfrentar a trabajadores con insumos. La atención requiere ambos. Para determinar dónde existe una restricción hay que comparar partidas equivalentes de 2026 y 2027, verificar sus ampliaciones y observar su ejecución. Las fichas recibidas no permiten sostener, sin completar esa conciliación, un porcentaje uniforme de recorte de medicamentos o una suba salarial asegurada.</p><h3>El antecedente de ejecución en Salud</h3><p>En el Cuadro 2.4, Salud devengó $1.224.578 millones sobre $3.356.553 millones vigentes: 36,5% al primer semestre de 2026, frente a 35,7% del total de ese mismo universo. El agregado sanitario está cerca del promedio. La discusión debe abrirse por programa, hospital, compras y metas físicas para identificar demoras específicas.</p><p>El devengado registra una obligación de pago reconocida. Una tasa semestral, aislada del calendario de compras, contratos y obras, no describe por sí sola el cumplimiento de prestaciones ni prueba una falla de atención.</p><a class="p27-action" href="/presupuesto/ejecucion/">Abrir el observatorio de ejecución</a></section>
<section id="salud-mental"><span class="p27-kicker">04 · SALUD MENTAL Y CUIDADOS COMUNITARIOS</span><h2>El presupuesto debe sostener la atención dentro y fuera del hospital</h2><p>El Mensaje menciona atención continua en Borda, Moyano, Tobar García, Alvear y Ameghino; telemedicina, neurodesarrollo infantojuvenil, equipos itinerantes y Casas Vinculares. La evaluación presupuestaria debe identificar qué partidas sostienen estos dispositivos y qué recursos llegan a los hospitales generales y a la red comunitaria.</p><p>El PPI asigna $4.024 millones a ampliaciones de consulta externa de Borda y Moyano. También enumera partidas separadas de puesta en valor en efectores de salud mental. Esas inversiones son sólo una parte de la política sanitaria: el presupuesto total de salud mental exige sumar gasto operativo y dispositivos con una clasificación común, evitando duplicaciones.</p><p>La Ley 26.657, artículo 9, orienta la atención hacia un abordaje comunitario e interdisciplinario. Su artículo 32 establece para el ámbito nacional una referencia mínima del 10% del presupuesto de salud y promueve que provincias y CABA adopten el mismo criterio. Para discutir ese parámetro en la Ciudad se necesita primero reconstruir el numerador completo y el universo comparable de Salud.</p><div class="p27-callout"><strong>Prioridad propuesta</strong><p>Identificar el financiamiento de salud mental, fortalecer equipos comunitarios y de atención primaria, y publicar recursos y metas para prevenir crisis, asegurar continuidad de cuidados y acompañar a las familias.</p></div><div class="p27-links"><a href="/publicaciones/informes/salud-mental-caba/">Informe especial de salud mental</a><a href="/observatorio/salud-mental/">Observatorio de salud mental</a></div></section>
<section id="obras"><span class="p27-kicker">05 · COMPROMISOS QUE SE PUEDEN SEGUIR</span><h2>Qué inversiones sanitarias aparecen en el proyecto</h2><p>El Plan Plurianual de Inversiones prevé $417.643 millones para el Ministerio de Salud en 2027 y $152.097 millones en cada uno de los años 2028 y 2029. La partida de puesta en valor de CeSAC es de $9.048 millones para 2027, equivalente al 2,17% del total sanitario de este plan. Mide ese renglón de inversión, no todo el presupuesto de atención primaria.</p><p>El gasto de capital del Ministerio en la Planilla 2 suma $435.618 millones y responde a otra clasificación. El PPI y esa planilla tienen alcances diferentes; se deben conciliar para explicar la diferencia. Las siguientes 30 filas son una selección del PPI, con el año y la página de cada fuente.</p><div class="p27-filter"><label for="work-filter">Tipo de inversión</label><select id="work-filter"><option value="all">Todas las inversiones seleccionadas</option><option value="hospital">Hospitales generales</option><option value="salud-mental">Salud mental</option><option value="atencion-primaria">Atención primaria</option><option value="equipamiento">Equipamiento hospitalario</option></select><span id="work-count" aria-live="polite">30 inversiones seleccionadas</span></div><div class="p27-table-wrap" tabindex="0" role="region" aria-label="Inversiones sanitarias seleccionadas, tabla con desplazamiento horizontal"><table><caption>Montos nominales del PPI 2027–2029 · millones de pesos</caption><thead><tr><th scope="col">Efector</th><th scope="col">Inversión</th><th scope="col">2027</th><th scope="col">2028</th><th scope="col">2029</th><th scope="col">Fuente</th></tr></thead><tbody>{works}</tbody></table></div><p class="p27-source">Cada inversión aparece una sola vez. Se omiten las filas padre que resumen estos mismos importes y las fuentes con asignación cero duplicadas.</p><h3>Presupuestar una obra es el comienzo del control</h3><p>Para cada compromiso proponemos registrar monto aprobado, modificaciones, licitación, fecha de inicio, avance físico, devengado y puesta en funcionamiento. Las obras en consulta externa y guardias deben verificarse también por su capacidad adicional de atención, con personal e insumos suficientes.</p><div class="p27-links"><a download href="/assets/data/presupuesto-2027-obras-sanitarias.csv">Descargar las inversiones seleccionadas</a><a href="/presupuesto/ejecucion/">Consultar gasto devengado</a></div></section>
<section id="contexto"><span class="p27-kicker">06 · LAS PRIORIDADES DEL CONJUNTO</span><h2>Qué cambia en el resto del presupuesto</h2><p>El proyecto prevé un gasto total de $24,094 billones y recursos de $24,096 billones. Educación, vivienda, trabajo, movilidad y ambiente también inciden sobre las condiciones de vida y la salud. La siguiente comparación conserva el mismo universo y la misma base que el capítulo sanitario.</p><div class="p27-table-wrap" tabindex="0" role="region" aria-label="Comparación por funciones, tabla con desplazamiento horizontal"><table><caption>Funciones del gasto · vigente 30/06/2026 y proyecto 2027 · millones de pesos</caption><thead><tr><th scope="col">Función</th><th scope="col">Vigente 2026</th><th scope="col">Proyecto 2027</th><th scope="col">Variación nominal</th><th scope="col" id="real-column">Variación real · 21,54%</th></tr></thead><tbody>{rows}</tbody></table></div><p>La función Vivienda y Urbanismo tiene $826.690 millones y crece 20,4% nominal: pierde aproximadamente 0,9% real en el escenario del bloque. Esa función agrupa organismos diferentes; su resultado no equivale a la variación del Instituto de Vivienda. Transporte crece 5,2% nominal y cae 13,5% real en ese escenario. Cultura y Trabajo también quedan por debajo de la inflación promedio estimada.</p><p>El gasto de capital pasa de $4,033 billones a $4,326 billones: +7,3% nominal y −11,8% real en el escenario del bloque. Los anuncios de inversión en subte deben evaluarse por su renglón específico, fuente de financiamiento y cronograma; el agregado de transporte responde a un universo más amplio.</p><h3>El margen fiscal y el financiamiento sanitario</h3><p>El resultado primario proyectado es de $593.204 millones. Los intereses de la deuda ascienden a $591.887 millones: equivalen al 99,78% de ese resultado. Tras intereses, el superávit financiero sería de $1.316 millones, apenas 0,0055% de los recursos. Es un margen estrecho ante desvíos de ingresos o gastos.</p><p>Esta relación no significa que el 99,78% del presupuesto se destine a deuda: los intereses son 2,46% del gasto total. Tampoco prueba un traslado directo desde Salud hacia intereses. Sí permite discutir cuánto margen deja el esquema para fortalecer servicios y cómo se los protegerá si los recursos efectivos quedan por debajo de lo previsto.</p><p>El artículo 4 incluye $755.576 millones de endeudamiento público e incremento de otros pasivos, y $613.916 millones de amortización de deuda y disminución de otros pasivos. Son fuentes y aplicaciones financieras: se presentan separadas del gasto corriente y de capital para evitar dobles conteos.</p><h3>Ingresos e impuestos también son parte de la discusión</h3><p>El paquete incorpora Código Fiscal, Ley Impositiva y Ley Arancelaria. La reducción de Patentes debe discutirse junto con su costo fiscal, distribución por capacidad contributiva y financiamiento de los servicios. Los alivios a hogares y pequeños contribuyentes pueden formar parte de una política progresiva; corresponde demostrar cómo se sostendrán las prestaciones públicas.</p><p>El proyecto de Código Fiscal, modificación 16 del artículo 1, propone bonificar el 100% de Ingresos Brutos a personas humanas prestadoras de servicios en las tres primeras categorías del régimen simplificado y el 75% en las cinco siguientes, sujeto a reglamentación. La Ley Impositiva, Anexo I artículo 44, fija un umbral de valuación fiscal de $41.140.000 para el adicional de 1% por cuota de ABL. El texto del proyecto es la referencia ante diferencias con cifras de presentación.</p></section>
<section id="territorio"><span class="p27-kicker">07 · COMUNAS Y DESIGUALDAD</span><h2>Separar el presupuesto de las comunas de la inversión que llega al territorio</h2><p>La Planilla 34 enumera presupuesto de cada entidad Comuna. Los ministerios también ejecutan gastos y obras localizadas en esos territorios. Por eso la comparación de entidades comunales sirve para examinar descentralización, pero no representa la inversión total en cada comuna ni su gasto sanitario total.</p><details><summary>Consultar las 15 entidades comunales</summary><table class="p27-simple"><caption>Proyecto 2027 · presupuesto de entidad Comuna · millones de pesos</caption><thead><tr><th scope="col">Entidad</th><th scope="col">Monto</th></tr></thead><tbody>{communes}</tbody></table></details><p>La lectura desde los barrios debe reunir necesidades, servicios disponibles y ejecución. Proponemos observar atención primaria, cuidados, vivienda y ambiente con indicadores comparables. La localización de una obra y la población beneficiaria se registran por separado: un hospital puede estar en un barrio y atender una población mucho más extensa.</p><div class="p27-links"><a href="/presupuesto/territorio/">Presupuesto y territorio</a><a href="/presupuesto/descentralizacion/">Descentralización</a><a download href="/assets/data/presupuesto-2027-comunas.csv">Descargar entidades comunales</a></div></section>
<section id="propuestas"><span class="p27-kicker">08 · UNA AGENDA PARA EL DEBATE</span><h2>Qué proponemos desde 100 Barrios</h2><ol class="p27-agenda"><li><strong>Recuperar prioridad presupuestaria para Salud.</strong> Tomar como referencia inicial su participación anterior y discutir el financiamiento necesario según necesidades y metas de atención.</li><li><strong>Fortalecer la atención primaria y la prevención.</strong> Identificar partidas por CeSAC, equipos, horarios, insumos y articulación con hospitales, con prioridad en las zonas de mayor necesidad.</li><li><strong>Garantizar condiciones de trabajo y recursos para atender.</strong> Informar cargos ocupados y vacantes, guardias, compras y provisión de medicamentos. Evaluar salarios y capacidad operativa con datos específicos.</li><li><strong>Dar visibilidad al financiamiento de salud mental.</strong> Reconstruir el gasto completo, fortalecer dispositivos comunitarios y discutir una trayectoria de financiamiento acorde con derechos y demanda.</li><li><strong>Vincular obras con capacidad de atención.</strong> Exigir cronogramas y avances verificables, junto con personal, equipamiento y recursos para poner en funcionamiento cada ampliación.</li><li><strong>Proteger servicios ante desvíos de ingresos.</strong> Explicitar criterios para modificaciones de crédito y discutir el costo y la distribución de beneficios tributarios.</li></ol><h3>Preguntas que el Ejecutivo debe responder</h3><p>¿Qué explica la pérdida de participación de Salud? ¿Cómo se distribuyen recursos por hospital, CeSAC y programa? ¿Cuál es la dotación efectivamente ocupada y qué puestos están vacantes? ¿Qué capacidad adicional de atención aportará cada obra y cuándo? ¿Cuánto se asigna a salud mental comunitaria, cuidados paliativos y prestaciones obstétricas? ¿Cómo se protegerán medicamentos y atención primaria si la recaudación es menor a la prevista?</p><p>Son preguntas para el debate y el control público. Su publicación no implica que se hayan presentado pedidos formales de información.</p><a class="p27-action" href="/prensa/presupuesto-2027-salud/">Leer la posición de 100 Barrios</a></section>
<section id="metodologia"><span class="p27-kicker">09 · CÓMO SE HIZO EL ANÁLISIS</span><h2>Datos, cálculos y posición política</h2><p>El informe distingue valores del proyecto, comparaciones calculadas y propuestas de 100 Barrios. Fecha de corte: 8 de octubre de 2026. Analiza la versión presentada el 30 de septiembre; el resultado del trámite legislativo debe incorporarse cuando se documente.</p><dl class="p27-method"><dt>Comparación nominal</dt><dd>Proyecto 2027 dividido por vigente 2026 al 30/06, menos uno.</dd><dt>Comparación real de escenario</dt><dd>Proyecto 2027 dividido por vigente 2026 multiplicado por el factor de precios promedio anual, menos uno. Factores: 1,2154 y 1,2300.</dd><dt>Participación</dt><dd>Monto de cada función dividido por gasto total del mismo universo y año. Los cálculos usan los valores completos disponibles; el texto redondea.</dd><dt>Referencia distributiva de Salud</dt><dd>Gasto total 2027 multiplicado por la participación exacta de Salud en 2026, menos el proyecto de Salud 2027.</dd><dt>Ejecución</dt><dd>Devengado dividido por crédito vigente con igual fecha y universo. Se interpreta junto con metas físicas y calendario de gasto.</dd><dt>Territorio</dt><dd>Se identifica entidad presupuestaria y efector. Se conserva la diferencia entre clasificación geográfica, ubicación física y población atendida.</dd></dl><p>Las fichas secundarias aportan hipótesis y preguntas, pero las cifras se cotejan con planillas originales. La selección de inversiones contiene una fila por partida: las cabeceras que repiten subtotales no se suman. La comparación real por tipo de gasto dentro de Salud requiere una base 2026 comparable que debe completarse antes de afirmarla.</p><div class="p27-links"><a download href="/assets/data/presupuesto-2027.json">Descargar datos y referencias</a><a download href="/assets/data/presupuesto-2027-funciones.csv">Descargar comparación por funciones</a><a href="/cepoes/metodologia/presupuesto/">Metodología del observatorio</a></div><h3 id="fuentes">Fuentes documentales</h3><ul class="p27-sources">{sources}<li>PDLEY 33/26, Código Fiscal: artículo 1, modificación 16, artículo 181 propuesto. PDLEY 34/26, Ley Impositiva: Anexo I, artículo 44. PDLEY 35/26, Ley Arancelaria: Anexo I, artículo 1. Documentos remitidos el 30/09/2026 y aportados para este análisis.</li><li><a href="https://drive.google.com/drive/folders/11YFiAEF_12Aqe93udiwkB6Pk1upSt_Yl" target="_blank" rel="noopener">Carpeta documental del presupuesto</a>: fichas de Salud, presentación de Hacienda y escenarios de deflactación. La carpeta puede requerir permiso de acceso; los datos utilizados se identifican en la descarga del informe.</li></ul></section></main>'''
title='Presupuesto CABA 2027 con la salud y los barrios en el centro'
def page(title,route,body,report=False):
 return '<!doctype html><html lang="es" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+' — CEPOES</title><meta name="description" content="Análisis del proyecto de Presupuesto 2027 desde 100 Barrios: salud pública, CeSAC, personal, salud mental, inversiones y prioridades territoriales.">'+ ('<meta name="cepoes:publication" content="report">' if report else '')+'<link rel="canonical" href="https://cepoes.org'+route+'"><meta property="og:type" content="article"><meta property="og:title" content="'+html.escape(title)+'"><meta property="og:url" content="https://cepoes.org'+route+'"><meta property="article:published_time" content="2026-10-08"><meta property="article:modified_time" content="2026-10-08"><link rel="stylesheet" href="/assets/site.css"><link rel="stylesheet" href="/assets/presupuesto-2027.css"><script defer src="/assets/common-r1.js?v=259"></script><script defer src="/assets/presupuesto-2027.js?v=1"></script></head><body class="p27-page" data-related-tags="presupuesto,salud,cuidados,territorio">'+body+'<script id="p27-data" type="application/json">'+json.dumps(D,ensure_ascii=False).replace('<','\\u003c')+'</script></body></html>'
path=SITE/'presupuesto/2027/index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(page(title,'/presupuesto/2027/',body,True))
press='''<main class="p27 p27-press"><p class="p27-crumb"><a href="/prensa/">Prensa</a> / Presupuesto 2027</p><span class="p27-kicker">100 BARRIOS · PRESUPUESTO 2027 · 8 DE OCTUBRE DE 2026</span><h1>La salud pública debe recuperar prioridad en el presupuesto porteño</h1><p class="p27-lead">El proyecto de Jorge Macri reduce el peso de Salud en el gasto de la Ciudad. Desde 100 Barrios proponemos fortalecer hospitales, CeSAC y salud mental, y discutir los recursos que garantizan atención en cada barrio.</p><p>El presupuesto muestra las prioridades de un gobierno. En el proyecto para 2027, Salud recibe $3,97 billones: un aumento de 18,2% en pesos respecto del crédito vigente al 30 de junio de 2026. Pero el presupuesto total crece 21,2%. Por eso la salud pública pierde participación: pasa del 16,89% al 16,46% del gasto.</p><p>Mantener su participación anterior requeriría aproximadamente $102.419 millones adicionales. Esa comparación expresa una alternativa de distribución dentro del mismo presupuesto y no depende de la inflación. Con el escenario de inflación promedio de 21,54% utilizado por el bloque Fuerza por Buenos Aires, la asignación a Salud cae además 2,8% en términos reales.</p><p>Desde 100 Barrios creemos que el debate debe comenzar por las necesidades de atención. Una obra en un hospital importa cuando se transforma en capacidad de atender: con equipos de salud, insumos, medicamentos y equipamiento en funcionamiento. La atención primaria y la salud mental comunitaria necesitan recursos identificables, metas y continuidad.</p><p>El proyecto anuncia ampliaciones en hospitales y prevé inversiones en CeSAC. Corresponde discutir su distribución, sus cronogramas y qué personal y recursos harán posible su funcionamiento. También necesitamos información sobre vacantes, turnos y tiempos de espera para evaluar si la asignación responde a las necesidades de la población.</p><p>La ejecución sanitaria agregada de 2026 no justifica acusaciones generales sin abrir los datos: el Mensaje informa 36,5% de devengado en Salud al primer semestre, cerca del 35,7% del conjunto. El análisis tiene que distinguir programas, compras, obras y prestaciones.</p><p>El contexto fiscal obliga a una discusión transparente. Los intereses proyectados de la deuda equivalen al 99,78% del superávit primario de 2027. Ante ese margen estrecho, el Gobierno debe explicar cómo protegerá los servicios esenciales si los recursos no alcanzan lo previsto.</p><p>Proponemos recuperar prioridad para Salud, fortalecer la prevención y los CeSAC, sostener condiciones de trabajo y provisión de insumos, identificar el financiamiento de salud mental y verificar que las obras se conviertan en atención efectiva. La salud pública es un derecho y debe ocupar el lugar que merece en el presupuesto de la Ciudad.</p><div class="p27-callout"><strong>La salud pública necesita presupuesto para atender</strong><p>Defendemos una red pública que acompañe a las personas cerca de donde viven, cuide a sus trabajadores y reduzca las desigualdades entre barrios.</p></div><p class="p27-source">Datos: proyecto PDLEY-2026-36, Planilla 1 y Mensaje, Cuadro 2.4 y esquema AIF. Base: vigente al 30/06/2026. Variaciones reales: escenario estimado, no inflación observada.</p><a class="p27-action" href="/presupuesto/2027/">Leer el análisis completo y consultar los datos</a></main>'''
path=SITE/'prensa/presupuesto-2027-salud/index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(page('La salud pública debe recuperar prioridad en el presupuesto porteño','/prensa/presupuesto-2027-salud/',press))
